function genScene(d = 5) {
var strP = createVector(width / 2, L);
var endP = createVector(width / 2, height - L);
  scene = new Shape(0, 0, width, height);
var biggestLenBetween = 0;
  for (let i = 0, dirR = 1; i < N; i++, dirR *= -1) {
var t1 = i / N;
var t2 = (i + 1) / N;
var p1 = p5.Vector.lerp(strP, endP, t1);
var p2 = p5.Vector.lerp(strP, endP, t2);

var lenBetween = map(abs(i - N / 2), 0, N / 2, S / 3, S / 10);
    if (lenBetween > biggestLenBetween) biggestLenBetween = lenBetween;
var b1 = p1.copy().add(dirR * lenBetween, 0);
var b2 = p1.copy().add(dirR * (lenBetween + L * random(0.8, 1.2)), 0);
var b3 = p2.copy().add(dirR * (lenBetween + L * random(0.8, 1.2)), 0);
var b4 = p2.copy().add(dirR * lenBetween, 0);

		// line seg
    if (lenBetween > d) {
      if (lenBetween < L || random() > 0.75) {
var lne = new ShapeSegLine(p1, b1);
        scene.addObj(lne);
      } else {
        insertLineBez(p1, b1);
      }
    }

		// bez seg
var bez = new ShapeSegBez(b1, b2, b3, b4);
    scene.addObj(bez);

		// line seg
		if (lenBetween > d) {
      if (lenBetween < L || random() > 0.75) {
        var lne = new ShapeSegLine(b4, p2);
        scene.addObj(lne);
      } else {
        insertLineBez(b4, p2);
      }
    }

    // last pt rewind
    if (false && i === N - 1) {
var p3 = p5.Vector.lerp(strP, endP, 0);
      var b1 = { x: p2.x - biggestLenBetween - L, y: p2.y };
      var b4 = { x: p3.x - biggestLenBetween - L, y: p3.y };
      var b2 = { x: b1.x - L, y: b1.y };
      var b3 = { x: b4.x - L, y: b4.y };

var lne1 = new ShapeSegLine(p2, b1);
      scene.addObj(lne1);
      var bez = new ShapeSegBez(b1, b2, b3, b4);
      scene.addObj(bez);
var lne2 = new ShapeSegLine(b4, p3);
      scene.addObj(lne2);
    }
  }

  scene.calcPts(PTS_DETAIL);
  // console.log(histogetNextT, getNextTIt);
}

// insert bulge
function insertLineBez(a, b) {
  // console.log(`insertLineBez(${a}, ${b})`);
var vec = createVector(b.x - a.x, b.y - a.y);
var th = random(0.3, 0.9); // thickness insertion bez in relation to L (height)
var f1 = random(0.1, 1 - th); // start f in relation to whole line (not math correct, cause th relates to L)
  var b1 = vec.copy().mult(f1).add(a);
  var b4 = vec
    .copy()
    .mult(f1 + (th * L) / vec.mag())
    .add(a);
var bv = p5.Vector.sub(b4, b1)
    .mult(random(0.4, 0.6))
    .rotate(random() < 0.5 ? HALF_PI : PI + HALF_PI);
  var b2 = b1.copy().add(bv);
  var b3 = b4.copy().add(bv);
  /*
  var lne = new ShapeSegLine(a, b);
  scene.addObj(lne);
  */
  var lne1 = new ShapeSegLine(a, b1);
  scene.addObj(lne1);
  var bez = new ShapeSegBez(b1, b2, b3, b4);
  scene.addObj(bez);
  var lne2 = new ShapeSegLine(b4, b);
  scene.addObj(lne2);
}

