/*
 * Shape, container fpr Lines / Beziers
 */

class Shape {
  constructor(x, y, w, h) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.ang = 0;
    this.objs = [];

    this.len = 0;
    this.ptI = 0; // pt index
    // this.pts = [];
  }

  draw() {
    for (let o of this.objs) {
      o.drawPts();
    }
  }

  addObj(obj) {
    this.objs.push(obj);
  }

  rotate(ang) {
var da = ang - this.ang;
    this.ang = ang;
  }

  calcPts(d = 10) {
    this.pts = [];
    for (let o of this.objs) {
      o.calcPts(d);
      for (let e of o.pts) {
        this.pts.push(e);
      }
    }
  }

  getNextPt(falseOnEnd = false) {
    if (!this.pts || this.pts.length < 1) return null;
var p = this.pts[this.ptI % this.pts.length];
    this.ptI++;
		if (falseOnEnd && this.ptI >= this.pts.length) return false;
    return p;
  }
}

/*
 * Line (Segment)
 */

class ShapeSegLine {
  constructor(a, b) {
    this.typ = "LINE";
    this.a = a;
    this.b = b;
    this.pts = [];
    this.len = dist(a.x, a.y, b.x, b.y);

    // this.pts = [];
  }

  calcPts(d = 5, delta = 0.01) {
    this.pts = [];
var n = max(1, this.len / d);
var a = createVector(this.b.x - this.a.x, this.b.y - this.a.y).heading();
    // console.log(this.len / d, n, 1 / n);
    for (let t = 0; t <= 1 + delta; t += 1 / n) {
      // { t, p, a };
var f = constrain(t, 0, 1);
      var p = {
        x: lerp(this.a.x, this.b.x, f),
        y: lerp(this.a.y, this.b.y, f),
      };
      this.pts.push({ t: f, p, a });
      if (abs(1 - t) < delta) break;
    }
  }

  draw() {
    this.drawLine();
  }

  drawPts() {
    if (!this.pts) this.calcPts();
    console.log("ss", this.pts);
    beginShape();
    for (let p of this.pts) {
      // p.p(oint) p.a(ngle) p.t
      vertex(p.p.x, p.p.y);
    }
    endShape();
  }

  drawLine() {
    line(this.a.x, this.a.y, this.b.x, this.b.y);
  }
}

/*
 * Bezier (Segment)
 */

class ShapeSegBez {
  constructor(p1, p2, p3, p4) {
    this.typ = "BEZ";
    this.p1 = p1;
    this.p2 = p2;
    this.p3 = p3;
    this.p4 = p4;
    this.pts = [];
    this.len = this.lenArcBez();
  }

  calcPts(d = 10) {
    this.pts = [];
    this.pts.push(this.getSeg());
    // beginShape();
    for (let i = 0, t = 0, td = 0; i < (this.len / d) * 1.1; i++) {
var nextT = this.getNextSeg(min(t + td, 1), d);
      this.pts.push(nextT);
      t = nextT.t;
      // vertex(nextT.p.x + 200, nextT.p.y);
      if (t + td > 1) break;
      if (td === 0) td = t / 10;
    }
    // endShape();
  }

  lenArcBez() {
var x1 = this.p1.x;
var y1 = this.p1.y;
var x2 = this.p2.x;
var y2 = this.p2.y;
var x3 = this.p3.x;
var y3 = this.p3.y;
var x4 = this.p4.x;
var y4 = this.p4.y;

    // 1) add dist from a to mid anchor to b
    {
var sum = 0;
var midP = {
        x: lerp(x2, x3, 0.5),
        y: lerp(y2, y3, 0.5),
      };
      sum += dist(x1, y1, midP.x, midP.y);
      sum += dist(x4, y4, midP.x, midP.y);
      // console.log(`1b) ${nf(sum, 0, 3)}`);
    }

    // 3nd) dist inbetween points
    {
      var sum = 0;
var num = 10;
      for (let i = 0; i < num; i++) {
        var t1 = i / num;
        var a = {
          x: bezierPoint(x1, x2, x3, x4, t1),
          y: bezierPoint(y1, y2, y3, y4, t1),
        };
        var t2 = (i + 1) / num;
var b = {
          x: bezierPoint(x1, x2, x3, x4, t2),
          y: bezierPoint(y1, y2, y3, y4, t2),
        };
var dst = dist(a.x, a.y, b.x, b.y);
        sum += dst;
      }
      // console.log(`3) ${nf(sum, 0, 3)}`);
      return sum;
    }

    return sum;
  }

  // only works for not crossing anchor points
  getSeg(t = 0) {
    var x1 = this.p1.x;
    var y1 = this.p1.y;
    var x2 = this.p2.x;
    var y2 = this.p2.y;
    var x3 = this.p3.x;
    var y3 = this.p3.y;
    var x4 = this.p4.x;
    var y4 = this.p4.y;

    var p = {
      x: bezierPoint(x1, x2, x3, x4, t),
      y: bezierPoint(y1, y2, y3, y4, t),
    };

    var a = createVector(
      bezierTangent(x1, x2, x3, x4, t),
      bezierTangent(y1, y2, y3, y4, t)
    ).heading();

    return { t, p, a };
  }

  getNextSeg(t_, desiredLen = 5, delta = 0.5) {
    histogetNextT++;
    var x1 = this.p1.x;
    var y1 = this.p1.y;
    var x2 = this.p2.x;
    var y2 = this.p2.y;
    var x3 = this.p3.x;
    var y3 = this.p3.y;
    var x4 = this.p4.x;
    var y4 = this.p4.y;

var st = {
      x: bezierPoint(x1, x2, x3, x4, t_),
      y: bezierPoint(y1, y2, y3, y4, t_),
    };

    var p,
      a,
      dst = 0,
      tries = 10,
      t1 = t_,
      t2 = 1,
      t = lerp(t1, t2, 0.5);
    for (let i = 0; i < tries; i++) {
      getNextTIt++;
      p = {
        x: bezierPoint(x1, x2, x3, x4, t),
        y: bezierPoint(y1, y2, y3, y4, t),
      };
      a = createVector(
        bezierTangent(x1, x2, x3, x4, t),
        bezierTangent(y1, y2, y3, y4, t)
      ).heading();
var currDist = dist(st.x, st.y, p.x, p.y);

      if (abs(desiredLen - currDist) < delta) {
        // console.log("#", currDist, desiredLen, delta, t)
        break;
      } else if (currDist > desiredLen) {
        t2 = t;
        t = lerp(t1, t, 0.5);
      } else {
        t1 = t;
        t = lerp(t, t2, 0.5);
      }

      // console.log(">", i, currDist, t, t1, t2);
    }

    // console.log(`getNextT() ${nf(t, 0, 3)}`);
    return { t, p, a };
  }

  draw() {
    this.drawBez();
  }

  drawPts() {
    beginShape();
    for (let p of this.pts) {
      // p.p(oint) p.a(ngle) p.t
      vertex(p.p.x, p.p.y);
    }
    endShape();
  }

  drawBez() {
    var bez = this;
    strokeWeight(1);
    bezier(
      this.p1.x,
      this.p1.y,
      this.p2.x,
      this.p2.y,
      this.p3.x,
      this.p3.y,
      this.p4.x,
      this.p4.y
    );
  }
}

