var N = 7; // number of returns, will be set in setup()
var PTS_DETAIL = 4; // distance between pts
var S, L, SW;
var scene;
var histogetNextT = 0,
  getNextTIt = 0;

function setup() {
  createCanvas((S = max(windowWidth, windowHeight)), S);
	describe("doodle of meandering wall with bulges, inspired by Richard Boeser");
  frameRate(60);
	colorMode(RGB);
  background("rgb(2, 2, 12)");
  colorMode(HSB, 1);
  L = ~~(S / 10);
  N = ~~random(4, 10);
  SW = L / 10;
  noFill();
  stroke("azure");
  strokeWeight(SW);
  genScene();
	loop();
}

